void file_closer(FILE* f) { if (f) fclose(f); }

// Define unique_ptr type with the deleter's signature
using FilePtr = std::unique_ptr<FILE, decltype(&file_closer)>;

// Instantiate: Passes raw pointer and the deleter function address
FILE* raw = fopen("config.cfg", "r");
FilePtr managed_file(raw, &file_closer); // RAII

// --- Using a lambda deleter for heap management ---

// Custom deleter (e.g., calling specialized close API or delete[])
auto resource_deleter = [](int* p) {
    std::cout << "Custom cleanup called.\n";
    delete[] p;
};

// Define type based on lambda's signature
using ResourcePtr = std::unique_ptr<int, decltype(resource_deleter)>;

ResourcePtr buffer(new int[5], resource_deleter);
